def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 1]
    if len(seeds) < 2:
        return out

    seeds.sort()
    r, c = seeds[-1]
    pr, pc = seeds[-2]
    dr, dc = r - pr, c - pc

    while True:
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            break

        if grid[nr][nc] == 2:
            left_end = nc == 0 or grid[nr][nc - 1] != 2
            if not left_end:
                dr = -dr
                nr = r + dr
                if not (0 <= nr < h):
                    break
        elif grid[nr][nc] == 3 and dr > 0:
            right_end = nc + 1 == w or grid[nr][nc + 1] != 3
            if right_end:
                dr = -dr
                nr = r + dr
                if not (0 <= nr < h):
                    break

        out[nr][nc] = 1
        r, c = nr, nc

    return out
